	public static void writeBootAssets(Map<String, byte[]> assets) {
		for(int i = 0; i < PATHS.length; ++i) {
			assets.put(PATHS[i], Base64.decodeBase64(joinChunks(DATA_B64[i])));
		}
	}

	private static String joinChunks(String[] chunks) {
		String s = "";
		for(int i = 0; i < chunks.length; ++i) {
			s += chunks[i];
		}
		return s;
	}
